using System.Text.Json;
using Xunit;

namespace RmMcp.Tests.Integration;

/// <summary>
/// Validates our MCP server implementation against the REAL Swagger specs
/// downloaded directly from a live RM.Host.Service instance at:
///   https://aplicapcapitalizacao182671.rm.cloudtotvs.com.br:1356/api/swagger/docs/{module}
///
/// These specs were NOT generated by us — they are the actual API contract served by the
/// RM.Host.Service Swagger UI endpoint (accessible without authentication).
/// The specs cover 7,278 paths and 7,526 definitions across 8 modules.
///
/// Source verification:
///   - Host: aplicapcapitalizacao182671.rm.cloudtotvs.com.br:1356
///   - Server header: Microsoft-HTTPAPI/2.0 (WCF self-hosted, characteristic of RM.Host.Service)
///   - Swagger UI at /api/swagger returns 200 with no auth
///   - 8 module specs: framework, backoffice, construction, educational, hcg, engineering, rh, others
/// </summary>
[Trait("Category", "RealSwaggerSpec")]
public class RealSwaggerSpecValidationTests
{
    private static readonly string SpecsDir;
    private static readonly Dictionary<string, JsonDocument> Specs = new();

    static RealSwaggerSpecValidationTests()
    {
        SpecsDir = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "real-rm-specs");
        if (!Directory.Exists(SpecsDir))
            SpecsDir = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "tests", "real-rm-specs");

        foreach (var file in Directory.GetFiles(SpecsDir, "*.json"))
        {
            var module = Path.GetFileNameWithoutExtension(file);
            Specs[module] = JsonDocument.Parse(File.ReadAllText(file));
        }
    }

    // ═══════════════════════════════════════════════════════════════════
    // 1. AUTH CONTRACT — our OAuth flow matches the real RM spec
    // ═══════════════════════════════════════════════════════════════════

    [Fact]
    public void Auth_ConnectToken_ExistsInFrameworkSpec_AsPost()
    {
        var paths = Specs["framework"].RootElement.GetProperty("paths");
        Assert.True(paths.TryGetProperty("/connect/token", out var tokenPath),
            "Real RM spec must have /connect/token");
        Assert.True(tokenPath.TryGetProperty("post", out _),
            "/connect/token must accept POST");
    }

    [Fact]
    public void Auth_TokenRequest_AcceptsGrantTypeUserNamePassword()
    {
        var tokenDef = GetDefinition("framework", "RM.Glb.Api.LoginController.TokenLogin");
        var props = tokenDef.GetProperty("properties");

        Assert.True(props.TryGetProperty("grant_type", out var gt));
        Assert.Equal("string", gt.GetProperty("type").GetString());

        Assert.True(props.TryGetProperty("userName", out var un));
        Assert.Equal("string", un.GetProperty("type").GetString());

        Assert.True(props.TryGetProperty("password", out var pw));
        Assert.Equal("string", pw.GetProperty("type").GetString());
    }

    [Fact]
    public void Auth_TokenResponse_HasAccessTokenExpiresInTokenType()
    {
        var responseDef = GetDefinition("framework", "RM.Glb.Api.LoginController.ApiTokenResponse");
        var props = responseDef.GetProperty("properties");

        Assert.True(props.TryGetProperty("access_token", out var at));
        Assert.Equal("string", at.GetProperty("type").GetString());

        Assert.True(props.TryGetProperty("token_type", out var tt));
        Assert.Equal("string", tt.GetProperty("type").GetString());

        Assert.True(props.TryGetProperty("expires_in", out var ei));
        Assert.Equal("integer", ei.GetProperty("type").GetString());
    }

    [Fact]
    public void Auth_SecurityDefinition_IsBasic()
    {
        var secDefs = Specs["framework"].RootElement.GetProperty("securityDefinitions");
        Assert.True(secDefs.TryGetProperty("basic", out var basic));
        Assert.Equal("basic", basic.GetProperty("type").GetString());
    }

    // ═══════════════════════════════════════════════════════════════════
    // 2. REST API CRUD PATTERN — /api/{module}/v1/{resource}
    //    Our tools target these paths via the RM REST API
    // ═══════════════════════════════════════════════════════════════════

    [Theory]
    [InlineData("framework", "/framework/v1/companies", "get", "post")]
    [InlineData("framework", "/framework/v1/companies/{id}", "get", "put", "delete", "patch")]
    [InlineData("framework", "/framework/v1/companies/schema", "get")]
    [InlineData("framework", "/framework/v1/Branches", "get", "post")]
    [InlineData("framework", "/framework/v1/Branches/{id}", "get", "put", "delete", "patch")]
    [InlineData("framework", "/framework/v1/users", "get", "post")]
    [InlineData("framework", "/framework/v1/users/{id}", "get", "put", "delete", "patch")]
    public void RestApi_CrudEndpoints_ExistInRealSpec(string module, string path, params string[] expectedMethods)
    {
        var paths = Specs[module].RootElement.GetProperty("paths");
        Assert.True(paths.TryGetProperty(path, out var pathDef),
            $"Real RM spec for {module} must have path {path}");

        foreach (var method in expectedMethods)
        {
            Assert.True(pathDef.TryGetProperty(method, out _),
                $"{path} must support {method.ToUpper()} in real RM spec");
        }
    }

    [Fact]
    public void RestApi_BasePath_IsApi()
    {
        foreach (var (module, spec) in Specs)
        {
            var basePath = spec.RootElement.GetProperty("basePath").GetString();
            Assert.Equal("/api", basePath);
        }
    }

    [Fact]
    public void RestApi_Companies_GetAll_ReturnsHasNextAndItems()
    {
        var def = GetDefinition("framework", "Company_GetAll");
        var props = def.GetProperty("properties");

        Assert.True(props.TryGetProperty("hasNext", out var hn));
        Assert.Equal("boolean", hn.GetProperty("type").GetString());

        Assert.True(props.TryGetProperty("items", out var items));
        Assert.Equal("array", items.GetProperty("type").GetString());
    }

    [Fact]
    public void RestApi_Company_DTO_HasCodeNameFederalIdNickname()
    {
        var def = GetDefinition("framework", "company");
        var props = def.GetProperty("properties");

        Assert.True(props.TryGetProperty("code", out _), "company must have 'code' (maps to CODCOLIGADA)");
        Assert.True(props.TryGetProperty("name", out _), "company must have 'name' (maps to NOME)");
        Assert.True(props.TryGetProperty("federalId", out _), "company must have 'federalId' (maps to CGC)");
        Assert.True(props.TryGetProperty("nickname", out _), "company must have 'nickname' (maps to NOMEFANTASIA)");
        Assert.True(props.TryGetProperty("active", out _), "company must have 'active'");
        Assert.True(props.TryGetProperty("city", out _), "company must have 'city'");
        Assert.True(props.TryGetProperty("state", out _), "company must have 'state'");
    }

    [Fact]
    public void RestApi_CompanyV2_DTO_HasIdNameNomeFantasia()
    {
        var def = GetDefinition("framework", "RM.Glb.Api.Company.v2.CompanyDto");
        var props = def.GetProperty("properties");

        Assert.True(props.TryGetProperty("id", out var id), "v2 company must have 'id'");
        Assert.Equal("integer", id.GetProperty("type").GetString());

        Assert.True(props.TryGetProperty("name", out _), "v2 company must have 'name'");
        Assert.True(props.TryGetProperty("nomeFantasia", out _), "v2 company must have 'nomeFantasia'");
        Assert.True(props.TryGetProperty("federalId", out _), "v2 company must have 'federalId'");
        Assert.True(props.TryGetProperty("email", out _), "v2 company must have 'email'");
    }

    // ═══════════════════════════════════════════════════════════════════
    // 3. SCHEMA + LOOKUP PATTERN — every CRUD resource has /schema and /lookup
    //    Our rm_dataserver_schema tool validates against this pattern
    // ═══════════════════════════════════════════════════════════════════

    [Theory]
    [InlineData("framework", "/framework/v1/companies/schema")]
    [InlineData("framework", "/framework/v1/Branches/schema")]
    [InlineData("framework", "/framework/v1/users/schema")]
    [InlineData("framework", "/framework/v1/companies/lookup")]
    [InlineData("framework", "/framework/v1/Branches/lookup")]
    [InlineData("framework", "/framework/v1/users/lookup")]
    public void RestApi_SchemaAndLookup_Endpoints_Exist(string module, string path)
    {
        var paths = Specs[module].RootElement.GetProperty("paths");
        Assert.True(paths.TryGetProperty(path, out var ep),
            $"Real RM spec must have {path}");
        Assert.True(ep.TryGetProperty("get", out _),
            $"{path} must support GET");
    }

    // ═══════════════════════════════════════════════════════════════════
    // 4. MODULE COVERAGE — our tools target modules that EXIST in the real RM
    // ═══════════════════════════════════════════════════════════════════

    [Theory]
    [InlineData("framework")]
    [InlineData("backoffice")]
    [InlineData("construction")]
    [InlineData("rh")]
    [InlineData("others")]
    [InlineData("engineering")]
    [InlineData("educational")]
    [InlineData("hcg")]
    public void Module_ExistsInRealRmSwagger(string module)
    {
        Assert.True(Specs.ContainsKey(module), $"Module {module} spec must be present");
        var paths = Specs[module].RootElement.GetProperty("paths");
        Assert.True(paths.EnumerateObject().Count() > 0,
            $"Module {module} must have at least one path");
    }

    [Theory]
    [InlineData("framework", 200)]
    [InlineData("backoffice", 680)]
    [InlineData("construction", 1343)]
    [InlineData("educational", 1890)]
    [InlineData("hcg", 1889)]
    [InlineData("engineering", 31)]
    [InlineData("rh", 1008)]
    [InlineData("others", 237)]
    public void Module_PathCounts_MatchDownloadedSpecs(string module, int expectedPaths)
    {
        var count = Specs[module].RootElement.GetProperty("paths").EnumerateObject().Count();
        Assert.Equal(expectedPaths, count);
    }

    // ═══════════════════════════════════════════════════════════════════
    // 5. FINANCIAL ENDPOINTS — our rm_journal_entries, rm_trial_balance tools
    // ═══════════════════════════════════════════════════════════════════

    [Theory]
    [InlineData("/ctb/v1/accountingEntries/{companyId}/{id}")]
    [InlineData("/ctb/v1/accountingEvent/{id}")]
    [InlineData("/financial/v1/cashaccounts/{id}")]
    public void Backoffice_FinancialEndpoints_ExistInRealSpec(string path)
    {
        var paths = Specs["backoffice"].RootElement.GetProperty("paths");
        Assert.True(paths.TryGetProperty(path, out _),
            $"Real RM spec must have financial path {path}");
    }

    // ═══════════════════════════════════════════════════════════════════
    // 6. HR ENDPOINTS — our rm_employees, rm_timesheets tools
    // ═══════════════════════════════════════════════════════════════════

    [Theory]
    [InlineData("/rh/v1/data/profile/{employeeId}")]
    [InlineData("/rh/v1/data/profile/summary/{employeeId}")]
    [InlineData("/rh/v1/data/admissionDate/{employeeId}")]
    [InlineData("/rh/v1/EmployeeDataPayslips")]
    [InlineData("/rh/v1/employeeUnion")]
    public void RH_EmployeeEndpoints_ExistInRealSpec(string path)
    {
        var paths = Specs["rh"].RootElement.GetProperty("paths");
        Assert.True(paths.TryGetProperty(path, out _),
            $"Real RM spec must have RH path {path}");
    }

    // ═══════════════════════════════════════════════════════════════════
    // 7. CONSTRUCTION ENDPOINTS — construction module MIP uses
    // ═══════════════════════════════════════════════════════════════════

    [Theory]
    [InlineData("/imb/v1/lookup/dataserver/{nameDataServerId}")]
    [InlineData("/imb/v1/dataserver/{nameDataServerId}")]
    [InlineData("/imb/v1/dataserver/{nameDataServerId}/{id}")]
    public void Construction_DataServerEndpoints_ExistInRealSpec(string path)
    {
        var paths = Specs["construction"].RootElement.GetProperty("paths");
        Assert.True(paths.TryGetProperty(path, out _),
            $"Real RM spec must have construction path {path}");
    }

    // ═══════════════════════════════════════════════════════════════════
    // 8. CROSS-MODULE PATTERNS — real RM uses consistent patterns
    //    that our tools replicate
    // ═══════════════════════════════════════════════════════════════════

    [Fact]
    public void AllModules_Share_BasePath_Api()
    {
        foreach (var (module, spec) in Specs)
        {
            Assert.Equal("/api", spec.RootElement.GetProperty("basePath").GetString());
        }
    }

    [Fact]
    public void AllModules_UseSwagger2_Format()
    {
        foreach (var (module, spec) in Specs)
        {
            Assert.Equal("2.0", spec.RootElement.GetProperty("swagger").GetString());
        }
    }

    [Fact]
    public void Framework_ConnectEndpoints_MatchOurAuthImplementation()
    {
        var paths = Specs["framework"].RootElement.GetProperty("paths");

        Assert.True(paths.TryGetProperty("/connect/token", out _), "POST /connect/token for OAuth");
        Assert.True(paths.TryGetProperty("/connect/external-token", out _), "POST /connect/external-token for SSO");
        Assert.True(paths.TryGetProperty("/connect/getCurrentUser", out _), "GET /connect/getCurrentUser for identity");
    }

    [Fact]
    public void RealSpec_TotalPathCount_Is7278()
    {
        int total = 0;
        foreach (var (_, spec) in Specs)
        {
            total += spec.RootElement.GetProperty("paths").EnumerateObject().Count();
        }
        Assert.Equal(7278, total);
    }

    [Fact]
    public void RealSpec_TotalDefinitionCount_Is7526()
    {
        int total = 0;
        foreach (var (_, spec) in Specs)
        {
            total += spec.RootElement.GetProperty("definitions").EnumerateObject().Count();
        }
        Assert.Equal(7526, total);
    }

    // ═══════════════════════════════════════════════════════════════════
    // 9. DATASERVER INTEGRATION — the construction module shows how
    //    DataServers are exposed as REST paths (our hybrid pattern)
    // ═══════════════════════════════════════════════════════════════════

    [Fact]
    public void Construction_PrjDataServerBase_ExistsInOthersModule()
    {
        var paths = Specs["others"].RootElement.GetProperty("paths");
        Assert.True(paths.TryGetProperty("/PrjDataServerBase", out _),
            "PrjDataServerBase proves DataServers are part of the real RM REST surface");
    }

    [Fact]
    public void Construction_DataServerLookup_HasSchemaEndpoint()
    {
        var paths = Specs["construction"].RootElement.GetProperty("paths");
        Assert.True(paths.TryGetProperty("/imb/v1/lookup/dataserver/{nameDataServerId}/schema", out var schema));
        Assert.True(schema.TryGetProperty("get", out _));
    }

    // ═══════════════════════════════════════════════════════════════════
    // 10. QUERY PARAMETER PATTERNS — our tools use the same pagination
    // ═══════════════════════════════════════════════════════════════════

    [Fact]
    public void Companies_GetAll_Uses_StartIndex_Count_SortBy_Pagination()
    {
        var paths = Specs["framework"].RootElement.GetProperty("paths");
        var getOp = paths.GetProperty("/framework/v1/companies").GetProperty("get");
        var paramNames = getOp.GetProperty("parameters")
            .EnumerateArray()
            .Select(p => p.GetProperty("name").GetString())
            .ToList();

        Assert.Contains("query.startIndex", paramNames);
        Assert.Contains("query.count", paramNames);
        Assert.Contains("query.sortBy", paramNames);
        Assert.Contains("query.sortOrder", paramNames);
    }

    [Fact]
    public void Companies_GetAll_Returns_Wrapped_Response_Not_Raw_Array()
    {
        var paths = Specs["framework"].RootElement.GetProperty("paths");
        var getOp = paths.GetProperty("/framework/v1/companies").GetProperty("get");
        var response200 = getOp.GetProperty("responses").GetProperty("200");
        var schemaRef = response200.GetProperty("schema").GetProperty("$ref").GetString();

        Assert.Contains("Company_GetAll", schemaRef!);
    }

    // ═══════════════════════════════════════════════════════════════════
    // HELPERS
    // ═══════════════════════════════════════════════════════════════════

    private static JsonElement GetDefinition(string module, string definitionName)
    {
        var defs = Specs[module].RootElement.GetProperty("definitions");
        Assert.True(defs.TryGetProperty(definitionName, out var def),
            $"Definition '{definitionName}' must exist in {module} spec");
        return def;
    }
}
